import { expect, test } from "bun:test";
import { validate } from "./subject.js";

test("ordinary urls pass, trimmed", () => {
  expect(validate("  https://example.com/a  ")).toBe("https://example.com/a");
});
test("non-http schemes are rejected", () => {
  expect(validate("javascript:alert(1)")).toBeNull();
});
test("a code point above U+00FF cannot ride in a header", () => {
  expect(validate("https://example.com/caf\u00e9")).toBeNull();
  expect(validate("https://example.com/\u65e5\u672c")).toBeNull();
});
test("control characters are rejected", () => {
  expect(validate("https://example.com/\u0001x")).toBeNull();
  expect(validate("https://example.com/a\nb")).toBeNull();
});
test("latin-1 still passes", () => {
  expect(validate("https://example.com/caf%C3%A9")).toBe("https://example.com/caf%C3%A9");
});
